import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { roomAPI } from '../services/api';

const Home = () => {
  const [rooms, setRooms] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchFeaturedRooms();
  }, []);

  const fetchFeaturedRooms = async () => {
    try {
      const response = await roomAPI.getAll({ limit: 3 });
      setRooms(response.data.rooms || []);
    } catch (error) {
      console.error('Erreur chargement salles:', error);
    } finally {
      setLoading(false);
    }
  };

  // Fonction pour obtenir l'URL de l'image
  const getRoomImage = (room) => {
    // Si la salle a une image stockée dans room.image
    if (room.image && room.image.image_url) {
      return `http://localhost:5000/uploads/rooms/${room.image.image_url}`;
    }
    
    // Si la salle a des images dans room.images (ancien format)
    if (room.images && room.images.length > 0) {
      return `http://localhost:5000/uploads/rooms/${room.images[0].image_url}`;
    }
    
    // Image par défaut
    return '/default-room.jpg';
  };

  return (
    <div className="main-content">
      <div className="card">
        <h1>Bienvenue sur la plateforme de réservation de salles</h1>
        <p className="description">
          Réservez la salle parfaite pour vos réunions, conférences ou événements.
          Des espaces professionnels dans toute l'algerie.
        </p>
        
        <div className="cta-buttons">
          <Link to="/rooms" className="btn btn-primary">
            Chercher et réserver une salle
          </Link>
        </div>
      </div>

      <div className="card">
        <h2>Salles populaires</h2>
        {loading ? (
          <p>Chargement des salles...</p>
        ) : rooms.length > 0 ? (
          <div className="rooms-grid">
            {rooms.map(room => (
              <div key={room.id} className="room-card">
                {/* Image de la salle */}
                <div className="room-image-container">
                  <img 
                    src={getRoomImage(room)} 
                    alt={room.title}
                    className="room-image"
                    onError={(e) => {
                      e.target.src = '/default-room.jpg';
                    }}
                  />
                </div>
                
                <h3>{room.title}</h3>
                <p>{room.city} • {room.capacity} personnes</p>
                <p className="price">{room.price_per_hour}DA/heure</p>
                <Link to={`/rooms/${room.id}`} className="btn btn-primary">
                  Voir détails
                </Link>
              </div>
            ))}
          </div>
        ) : (
          <p>Aucune salle disponible pour le moment.</p>
        )}
      </div>

     
      
      <style jsx>{`
        .room-image-container {
          width: 100%;
          height: 180px;
          overflow: hidden;
          border-radius: 8px 8px 0 0;
          margin-bottom: 15px;
        }
        
        .room-image {
          width: 100%;
          height: 100%;
          object-fit: cover;
          transition: transform 0.3s ease;
        }
        
        .room-image:hover {
          transform: scale(1.05);
        }
        
        .room-card {
          display: flex;
          flex-direction: column;
          padding: 0;
          overflow: hidden;
        }
        
        .room-card h3 {
          margin: 0 15px 10px 15px;
          font-size: 1.2rem;
        }
        
        .room-card p {
          margin: 0 15px 5px 15px;
          color: #666;
        }
        
        .room-card .price {
          color: #337a519f;
          font-weight: bold;
          font-size: 1rem;
          margin: 10px 15px;
        }
        
        .room-card .btn {
          margin: 10px;
          margin-top: auto;
        }
        
        .rooms-grid {
          display: grid;
          grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
          gap: 20px;
          margin-top: 20px;
        }
        
        .features-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
          gap: 20px;
          margin-top: 20px;
        }
        
        .feature {
          text-align: center;
          padding: 20px;
          background: #f8f9fa;
          border-radius: 8px;
        }
        
        .feature h3 {
          color: #3498db;
          margin-bottom: 10px;
        }
        
        @media (max-width: 768px) {
          .rooms-grid {
            grid-template-columns: 1fr;
          }
          
          .features-grid {
            grid-template-columns: 1fr;
          }
        }
      `}</style>
    </div>
  );
};

export default Home;
